ification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://oregoninsuranceappraiser.com/#website","url":"https://oregoninsuranceappraiser.com/","name":"Oregon Insurance Appraiser","publisher":{"@id":"https://oregoninsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#webpage","url":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/","name":"Insurance Claim Dictionary | ACV, RCV, Umpire & More","description":"Searchable insurance claim dictionary: actual cash value, replacement cost, depreciation, appraisal award, umpire, FAIR Plan, DFR and more.","inLanguage":"en-US","isPartOf":{"@id":"https://oregoninsuranceappraiser.com/#website"},"about":{"@id":"https://oregoninsuranceappraiser.com/#business"},"publisher":{"@id":"https://oregoninsuranceappraiser.com/#business"},"dateModified":"2026-11-16","primaryImageOfPage":{"@type":"ImageObject","@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#primaryimage","url":"https://oregoninsuranceappraiser.com/assets/img/photos/roof-shingles.webp","width":960,"height":526},"breadcrumb":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#breadcrumb"},"mainEntity":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://oregoninsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim dictionary","item":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/"}],"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Oregon property insurance claim dictionary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. The first payment under most replacement cost policies.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while a home is repaired, such as rent and meals above normal.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the damage. The only question an appraisal panel decides.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either side demand appraisal when they disagree on the amount of loss.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Atmospheric river","description":"A long band of moisture that brings heavy rain and sometimes strong wind to the Pacific Northwest.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy condition that can reduce payment if the property was insured for less than a required percentage of its value.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Contents (Coverage C)","description":"Coverage for personal belongings.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing limits, deductibles, coverages and the policy period.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss the policyholder pays before the insurer pays.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age and condition. Often recoverable after repairs under replacement cost policies.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser without a financial stake in the outcome beyond a fee, as most appraisal clauses require.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Division of Financial Regulation (DFR)","description":"The Oregon agency, within the Department of Consumer and Business Services, that regulates insurance and handles consumer complaints.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Dwelling (Coverage A)","description":"Coverage for the house itself and attached structures.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Earthquake endorsement","description":"Optional coverage added to a property policy for earthquake damage, usually with a percentage deductible.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Estimate","description":"An itemized list of repair work with quantities and prices.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Extended replacement cost","description":"An endorsement that pays above the dwelling limit, often by 20% to 50%, if rebuilding costs more than expected.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A state-established insurer of last resort. In Oregon, the Oregon FAIR Plan Association.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld until repairs are complete.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as a quantity of shingles or square feet of drywall.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"Whether new materials can reasonably match undamaged ones in color, texture and style.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage after a loss, such as tarping or water extraction.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of meeting building codes when repairing or rebuilding.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Other structures (Coverage B)","description":"Coverage for detached structures such as garages, fences and sheds.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge for coordinating a multi-trade repair, commonly 10% plus 10%.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of the dwelling limit rather than a flat dollar amount.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, written as inches of rise per 12 inches of run.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Policy limit","description":"The maximum the insurer will pay under a coverage.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, often required within a set time after the insurer requests it.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional who represents policyholders in handling and negotiating a claim for a fee.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation paid once repairs or replacement are completed.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer says it is handling the claim while reserving the right to deny coverage later.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of what is damaged and what work is needed to repair it.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Smoke infiltration","description":"Smoke and soot entering a structure from a nearby fire, including wildfire.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Square","description":"100 square feet of roof surface.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on steep roofs, usually 7/12 pitch and above.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right to recover what it paid from a third party who caused the loss.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy’s deadline to file a lawsuit, commonly two years from the loss in Oregon.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missed or underpriced in the original estimate.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the appraisers can’t agree on.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Unfair claim settlement practices","description":"Insurer conduct prohibited by statute; in Oregon, listed in ORS 746.230.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Wildland-urban interface (WUI)","description":"Areas where homes meet or mix with undeveloped wildland vegetation and face higher wildfire risk.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Widely used estimating software for property insurance claims.","inDefinedTermSet":{"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}}],"@id":"https://oregoninsuranceappraiser.com/insurance-claim-dictionary/#definedtermset"}]}</script>
</head>
